 const overlapById=new Map(all.map(t=>[t.id,PresetTools.overlaps(t.url,previewPresets,p.id)]));const overlap=t=>{const others=overlapById.get(t.id)||[];return others.length?` · Cũng khớp preset: ${others.map(x=>x.name).join(', ')}`:''};const overlapCount=fresh.filter(t=>(overlapById.get(t.id)||[]).length).length;
