 showDialog(`<h2>Bảo vệ website</h2><p>Mỗi dòng một tên miền, ví dụ example.com. Bảo vệ cả tên miền con, không phân biệt tài khoản hay đường dẫn. Để trống để bỏ toàn bộ bảo vệ; thay đổi này có hiệu lực ngay.</p><label class="field">Tên miền<textarea name="domains" rows="7" placeholder="example.com&#10;work.example.org">${esc(shown.join('\n'))}</textarea></label><div class="dialogactions"><button class="secondary" value="cancel">Hủy</button><button class="primary">Lưu bảo vệ</button></div>`,async(f,d)=>{const latest=await chrome.storage.local.get('protectedDomains');if(JSON.stringify(latest.protectedDomains??null)!==original)throw Error('Danh sách bảo vệ đã thay đổi ở nơi khác; hãy mở lại.');const domains=Protection.parse(f.get('domains'));await chrome.storage.local.set({protectedDomains:domains});d.close();await load();notify('Đã cập nhật bảo vệ website.')});
