function render(){ $('#sideOpen').textContent=$('#statOpen').textContent=tabs.length;$('#sideInbox').textContent=groups.find(g=>g.id==='inbox')?.items.length||0;$('#sideSessions').textContent=snapshots.length;$('#sideHistory').textContent=batches.length;$('#sideTrash').textContent=trash.length;$('#sidePresets').textContent=presets.length;$('#sideTags').textContent=SearchTools.collectTags(groups).length;$('#sideDuplicates').textContent=DuplicateTools.find(tabs).length;const n=groups.reduce((s,g)=>s+g.items.length,0);$('#sideSaved').textContent=$('#statSaved').textContent=n;$('#statGroups').textContent=groups.length;$('#sideGroups').innerHTML=[...groups.filter(g=>g.favorite),...groups.filter(g=>!g.favorite)].map(g=>`<button class="sidegroup" data-action="goto-group" data-group="${esc(g.id)}"><span style="color:${esc(g.color)}">${esc(g.icon)}</span>${esc(g.name)}${g.favorite?' ★':''}</button>`).join('');document.querySelectorAll('.nav[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const labels={search:['Tìm tất cả','Tìm đồng thời trong tab, nhóm, phiên, preset và lịch sử dọn.'],tags:['Tag','Các nhãn của nhóm và tab đã lưu.'],open:['Tab đang mở','Mọi trang bạn đang mở, gọn gàng ở một nơi.'],duplicates:['Tab trùng URL','Xem các tab có cùng địa chỉ và chọn những tab cần xử lý.'],saved:['Nhóm đã lưu','Những trang quan trọng, sẵn sàng khi bạn cần.'],inbox:['Hộp để sau','Lưu nhanh, rồi phân loại khi bạn sẵn sàng.'],domains:['Theo tên miền','Xem các tab đã lưu theo website, không thay đổi nhóm gốc.'],trash:['Thùng rác','Khôi phục dữ liệu đã lưu hoặc xóa vĩnh viễn.'],history:['Lịch sử dọn','Xem kết quả từng lượt lưu và đóng.'],presets:['Preset dọn tab','Tìm các trang liên quan và tự quyết định điều gì xảy ra.'],sessions:['Phiên đã lưu','Lưu lại các cửa sổ để quay lại khi bạn cần.'],settings:['Cài đặt & sao lưu','Kiểm soát dữ liệu và không gian của bạn.']};$('#title').innerHTML=esc(labels[view][0])+' <span>✳</span>';$('#crumb').textContent=labels[view][0];$('#subtitle').textContent=labels[view][1];$('#eyebrow').textContent=view==='saved'?'THƯ VIỆN CỦA BẠN':'KHÔNG GIAN LÀM VIỆC';$('.toolbar').classList.toggle('hidden',view==='settings');$('#openFilters').classList.toggle('hidden',view!=='open');if(view==='open')renderOpenFilters();$('#selectAll').classList.toggle('hidden',view!=='open'&&view!=='duplicates');$('#saveSelected').classList.toggle('hidden',view!=='open'&&view!=='duplicates');$('#selectionBar').classList.toggle('hidden',(view!=='open'&&view!=='duplicates')||selected.size===0);$('#selectedCount').textContent=`Đã chọn ${selected.size} tab`;$('#saveSelected').disabled=!selected.size;const hasBulk=['saved','inbox','domains','sessions','trash'].includes(view);$('#bulkBar').classList.toggle('hidden',!hasBulk);$('#bulkCount').textContent=`Đã chọn ${bulkSelected.size} mục`;$('#bulkDelete').disabled=!bulkSelected.size;$('#bulkDelete').textContent=view==='trash'?'Xóa vĩnh viễn':'Chuyển vào thùng rác';$('#bulkRestore').classList.toggle('hidden',view!=='trash');$('#bulkRestore').disabled=!bulkSelected.size;$('#bulkOpen').classList.toggle('hidden',!['saved','inbox','domains'].includes(view));$('#bulkOpen').disabled=!bulkSelected.size;$('#bulkTags').classList.toggle('hidden',!['saved','inbox','domains'].includes(view));$('#bulkTags').disabled=!bulkSelected.size;$('#bulkMove').classList.toggle('hidden',!['saved','inbox','domains'].includes(view));$('#bulkMove').disabled=!bulkSelected.size;$('#bulkCopy').classList.toggle('hidden',!['saved','inbox','domains'].includes(view));$('#bulkCopy').disabled=!bulkSelected.size;$('#bulkClear').disabled=!bulkSelected.size;if(view==='open')renderOpen();else if(view==='saved'||view==='inbox')renderSaved();else if(view==='domains')renderDomains();else if(view==='duplicates')renderDuplicates();else if(view==='sessions')renderSessions();else if(view==='presets')renderPresets();else if(view==='history')renderHistory();else if(view==='trash')renderTrash();else if(view==='search')renderSearch();else if(view==='tags')renderTags();else renderSettings();updateBulkVisibility()}
function confirmAction(title,description,action){showDialog(`<h2>${esc(title)}</h2><p>${esc(description)}</p><div class="dialogactions"><button class="secondary" value="cancel">Hủy</button><button class="danger-soft">Xác nhận</button></div>`,async(_f,d)=>{await action();d.close();await load()})}
function validateImport(data){if(!data||data.format!=='tabspace-backup'||![1,2].includes(data.version)||!Array.isArray(data.groups))throw Error('File không đúng định dạng hoặc phiên bản không hỗ trợ.');if(data.groups.length>10000)throw Error('File chứa quá nhiều nhóm.');if(data.groups.filter(g=>g?.id==='inbox').length>1)throw Error('File có nhiều Hộp để sau.');return data.groups.map(g=>{if(typeof g.name!=='string'||!Array.isArray(g.items)||g.items.length>100000)throw Error('Nhóm không hợp lệ.');return {id:g.id==='inbox'?'inbox':id(),name:g.name.slice(0,80),icon:typeof g.icon==='string'?g.icon.slice(0,8):'✦',color:/^#[0-9a-f]{6}$/i.test(g.color)?g.color:'#7564d6',createdAt:Number(g.createdAt)||Date.now(),tags:OrganizeTools.importTags(g.tags),note:OrganizeTools.note(g.note),favorite:g.favorite===true,collapsed:g.collapsed===true,items:g.items.map(x=>{if(!validUrl(x.url)||typeof x.title!=='string')throw Error('File có tab không hợp lệ.');return{id:id(),url:x.url,title:x.title,createdAt:Number(x.createdAt)||Date.now(),tags:OrganizeTools.importTags(x.tags),note:OrganizeTools.note(x.note)}})}})}
